def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Number must be non-negative")
    if number == 0:
        return 0.0

    guess = number
    tolerance = 1e-10
    while True:
        next_guess = 0.5 * (guess + number // guess)
        if abs(next_guess - guess) < tolerance:
            return next_guess
        guess = next_guess
```

