def cal_sum(n):
    def is_perrin(number, n):
        x = number % n
        y = number // n

        # Calculate PP^k - P^(k-1) mod n
        k = 1
        while power_sequence(x, k) - power_sequence(y, k) != number % n:
            k += 1

        if k == 1:
            return True
        else:
            return (power_sequence(x, k - 1) - (x - y + n) // n + 1) == number % n
    def power_sequence(num, k):
        if k == 0:
            return 1
        return num * power_sequence(num, k - 1)

    count = 0
    for number in range(1, n * n):
        if is_perrin(number, n):
            count += 1

    return count
```

