def get_max_sum(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 1:
        return 1
    max_sum = n
    for divisor in [2, 3, 4, 5]:
        if n % divisor == 0:
            res = get_max_sum(n // divisor, memo)
            if res > max_sum:
                max_sum = res
    memo[n] = max_sum
    return max_sum
```

