def check_Consecutive(l):
    max_run = 0
    current_run = 0

    for i in range(len(l)):
        if i < len(l) - 1 and l[i+1] - l[i] == 1:
            current_run += 1
        else:
            max_run = max(max_run, current_run)
            current_run = 0
    return max_run > 1
