def comb_sort(nums):
    gap = len(nums) - 1
    swapped = True

    while gap > 0 or swapped:
        gap = max(1, gap // 1.25)  # shrinkage factor 1.25
        swapped = False
        for i in range(0, len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True
    return nums
