def find_accounts_with_rolling_high_transactions(filename):
    with open(filename) as f:
        transactions = []
        for line in f:
            parts = line.strip().split(',')
            if len(parts) == 3:
                try:
                    transactions.append((
                        int(parts[0]) if parts[0].isdigit() else None,  # date could be numeric (YYYY as int)
                        parts[1],
                        float(parts[2].replace(',', ''))  # handle commas in amount
                    ))
                except:
                    continue

    # Filter out invalid transactions (non-numeric amounts)
    valid_transactions = [(d, acc, a) for d, acc, a in transactions if isinstance(a, (int, float))]

    account_data = {}
    for d, acc, a in sorted(valid_transactions, key=lambda x: x[0]):  # Sort by date first

        if acc not in account_data:
            account_data[acc] = []
        account_data[acc].append((d, a))

    result = {}

    for acc, t_list in account_data.items():
        if not t_list:  # Skip accounts with no transactions
            continue

        t_list_sorted = sorted(t_list, key=lambda x: x[0])  # Ensure we have sorted by date again
        consecutive_streaks = []
        current_streak_start_end = (t_list_sorted[0][0], t_list_sorted[0][0])

        for i in range(1, len(t_list_sorted)):
            date = t_list_sorted[i][0]

            # Check if dates are consecutive (not more than 3 days apart)
            if date - current_streak_start_end[0] < 7 and date >= current_streak_start_end[0] + 1:
                # Keep current streak
                current_streak_end = date
            else:
                # Start new streak
                consecutive_streaks.append((current_streak_start_end[0], current_streak_end))
                current_streak_start_end = (date, date)

        # Add the last streak
        consecutive_streaks.append(current_streak_start_end)

        for window_start, window_end in consecutive_streaks:
            # Process transactions in this 7-day window (inclusive)
            window_transactions = [
                (d, a) for d, a in t_list_sorted
                if window_start <= d <= window_end
                and ((a >= 10000) or (a > -10000 and -a >= 10000))
            ]

            if len(window_transactions) >= 3:
                remaining_amounts = [a for d, a in window_transactions]
                pos_amts = sum(1 for a in remaining_amounts if a >= 10000)
                neg_amts = sum(1 for a in remaining_amounts if a < 0 and -a >= 10000)

                if pos_amts >= 3 or neg_amts >= 3:
                    # Convert date to 'YYYY-MM-DD' format
                    date_str = f"{window_start:04d}-{chr(ord('0') + (window_start//100)%10):02d}-{chr(ord('0') + (window_start%100)//10):02d}"
                    result[(acc, window_start)] = date_str

    # Format results
    for (acc_id, window_start), start_date in result.items():
        print(f"{acc_id} with transactions >= 10000 in any rolling 7-day window starting on {start_date} (
        transactions: at least 3)")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python script.py transactions.csv")
        sys.exit(1)

    find_accounts_with_rolling_high_transactions(sys.argv[1])
