def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of negative number using real numbers")
    if number == 0:
        return 0
    x = number
    y = 1
    while not is_equal_float(x, y):
        x = (x + number / x) / 2
        y = x
    return x

def is_equal_float(a, b, epsilon=1e-10):
    return abs(a - b) < epsilon
```

