def perrin(index):
    if index == 0:
        return [1, 1]
    prev = perrin(index - 1)
    prev_calc = prev[0] * prev[1] + prev[0] * prev[1] + prev[1] * prev[0]
    current = prev_calc % 10
    next_pair = tuple(map(lambda x: (x % 10) + prev_calc % 10, prev))
    return list(current) + list(next_pair) if isinstance(prev_calc, int) else list((current % 10) + next_pair)

def calculate_perrin_sum(n):
    current = perrin(n)
    return sum(int(num) for num in current)

def cal_sum(n):
    return calculate_perrin_sum(n)
