import math

def next_Perfect_Square(N):
    if N < 0:
        raise ValueError("Input must be a non-negative integer")

    if N == 0:
        return 1

    sqrt_N = math.isqrt(N)
    if sqrt_N * sqrt_N == N:
        return (sqrt_N + 1) ** 2
    else:
        return (sqrt_N + 1) ** 2
